/**
 * Auto-Done Writer: mark a task done and cascade ready status to dependents.
 *
 * Called by dispatchReviewResult when terminal_status === "passed".
 *
 * Steps:
 *   1. Checkout + sync the task branch on the management repo.
 *   2. Write done status and log entry to the task YAML.
 *   3. Apply the auto-ready cascade via applyAutoReadyRule.
 *   4. Commit all mutated YAMLs (task + any newly-readied siblings) in one commit.
 *   5. Push to the task branch.
 *   6. Report whether all tasks in the feature are now done (for Handoff Trigger).
 */

import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, featuresRoot, TASKS_DIR } from "../paths.js";
import { buildGitEnv } from "../git-env.js";
import { applyAutoReadyRule } from "./unblock-deps.js";
import { parseManagementRepoCoords } from "../config/workspace-config.js";

export interface WriteDoneAndCascadeOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  /** PR URL of the approved implementation PR — included in the done log note. */
  prUrl?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

export interface WriteDoneAndCascadeResult {
  /** Error string if the operation failed; undefined on success. */
  error?: string;
  /** Task IDs that were transitioned from todo → ready by the cascade. */
  readiedTaskIds: string[];
  /** True when every task in the feature is now done after this operation. */
  allTasksDone: boolean;
}

/**
 * Mark a task done, apply the auto-ready cascade, commit, and push.
 *
 * Non-throwing: returns an error string on failure so the caller can decide
 * whether to surface it as an event or halt the cycle.
 */
export function writeDoneAndCascade(opts: WriteDoneAndCascadeOpts): WriteDoneAndCascadeResult {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    prUrl,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const empty: WriteDoneAndCascadeResult = { error: undefined, readiedTaskIds: [], allTasksDone: false };

  // Step 1: Anchor to the task branch tip (branch checkout + sync protocol).
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    // Safety check: refuse to discard uncommitted changes (git hard-reset safety rule).
    const statusOut = execSync(`git -C "${workspaceRoot}" status --short`, { env, stdio: "pipe" }).toString().trim();
    if (statusOut.length > 0) {
      return { ...empty, error: `git reset safety: uncommitted changes detected:\n${statusOut}` };
    }
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
    // Step 4 of branch checkout+sync protocol: rebase onto base branch so that
    // checkAllTasksDone reads sibling YAMLs reflecting tasks merged to main after
    // this branch was last pushed — without this, those tasks appear non-done and
    // block the all_tasks_done event (and T9 Handoff Trigger).
    let baseBranch = "main";
    try { baseBranch = parseManagementRepoCoords(workspaceRoot).baseBranch; } catch { /* default to main */ }
    execSync(`git -C "${workspaceRoot}" rebase "origin/${baseBranch}"`, { env, stdio: "pipe" });
  } catch (e) {
    return { ...empty, error: `git fetch/checkout task branch failed: ${String(e)}` };
  }

  // Step 2: Read + mutate the task YAML.
  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return { ...empty, error: `failed to read task YAML: ${String(e)}` };
  }

  const now = new Date().toISOString();
  task.status = "done";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({
    action: "done",
    by: gitAuthorEmail,
    at: now,
    note: prUrl
      ? `Reviewer approved. PR: ${prUrl}`
      : "Reviewer approved.",
  });

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return { ...empty, error: `failed to write task YAML: ${String(e)}` };
  }

  // Step 3: Apply the auto-ready cascade (reads/writes sibling YAMLs on disk).
  const cascadeResult = applyAutoReadyRule({
    workspaceRoot,
    featureId,
    completedTaskId: taskId,
    gitAuthorEmail,
  });

  // Step 4: Commit all mutated YAMLs in a single commit.
  const filesToAdd = [relPath, ...cascadeResult.mutatedRelPaths];
  try {
    for (const f of filesToAdd) {
      execSync(`git -C "${workspaceRoot}" add "${f}"`, { env, stdio: "pipe" });
    }
    const cascadeNote = cascadeResult.readiedTaskIds.length > 0
      ? `; ready: ${cascadeResult.readiedTaskIds.join(", ")}`
      : "";
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): status → done${cascadeNote}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return { ...empty, error: `git add/commit failed: ${String(e)}` };
  }

  // Step 5: Push to the task branch.
  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return { ...empty, error: `git push failed: ${push.stderr}` };
  }

  // Step 6: Check if all tasks in the feature are now done.
  const allTasksDone = checkAllTasksDone(workspaceRoot, featureId, taskId);

  return {
    error: undefined,
    readiedTaskIds: cascadeResult.readiedTaskIds,
    allTasksDone,
  };
}

/**
 * Scan all task YAMLs in the feature and return true only when every task
 * (including the just-completed one) has status "done" or "cancelled".
 * Cancelled tasks do not block completion.
 */
function checkAllTasksDone(
  workspaceRoot: string,
  featureId: string,
  completedTaskId: string,
): boolean {
  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  let files: string[] = [];
  try {
    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
  } catch {
    return false;
  }

  for (const file of files) {
    try {
      const t = parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task;
      if (t.id === completedTaskId) continue; // just marked done in this call
      if (t.status !== "done" && t.status !== "cancelled") return false;
    } catch {
      return false;
    }
  }
  return files.length > 0;
}

