1	/**
2	 * Dispatch handler for reviewer-executor completions (handle.kind = "review").
3	 *
4	 * Routes by ReviewerResult.terminal_status:
5	 *   passed           → Auto-Done Writer: mark task done + auto-ready cascade
6	 *   change_requested → mutate task YAML to change_requested
7	 *   escalate         → post Slack, mutate task YAML to blocked, emit task_escalated
8	 *   unknown          → emit review_result_unknown_status
9	 */
10	
11	import type { ReviewerResult } from "@workflow/runtime-abi";
12	import { taskBranchName } from "../paths.js";
13	import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
14	import { writeDoneAndCascade } from "./write-done-and-cascade.js";
15	import { readTask } from "../utils/task-yaml-io.js";
16	import { handleEscalation } from "./escalation-handler.js";
17	
18	export type ReviewResult = ReviewerResult;
19	
20	export interface DispatchReviewResultOpts {
21	  result: ReviewResult;
22	  workspaceRoot: string;
23	  featureId: string;
24	  taskId: string;
25	  /** Task title from the task YAML — used in Slack escalation message. */
26	  taskTitle?: string;
27	  /** Implementation PR URL — used in Slack escalation message. */
28	  prUrl?: string;
29	  gitAuthorEmail: string;
30	  gitAuthorName?: string;
31	  sshKeyPath?: string;
32	  emit: (event: Record<string, unknown>) => void;
33	}
34	
35	export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
36	  const {
37	    result, workspaceRoot, featureId, taskId,
38	    taskTitle, prUrl,
39	    gitAuthorEmail, gitAuthorName, sshKeyPath, emit,
40	  } = opts;
41	  const taskBranch = taskBranchName(featureId, taskId);
42	
43	  switch (result.terminal_status) {
44	    case "passed": {
45	      emit({ type: "review_passed", task_id: taskId, feature_id: featureId,
46	             verdict: result.verdict, confidence: result.confidence, notes: result.notes, review_url: result.review_url });
47	
48	      let taskPrUrl: string | undefined;
49	      try {
50	        const existingTask = readTask(workspaceRoot, featureId, taskId);
51	        taskPrUrl = existingTask.pr?.url || undefined;
52	      } catch { /* non-fatal — fall back to no URL */ }
53	
54	      const doneResult = writeDoneAndCascade({
55	        workspaceRoot, featureId, taskId, taskBranch,
56	        prUrl: taskPrUrl,
57	        gitAuthorEmail, gitAuthorName, sshKeyPath,
58	      });
59	
60	      if (doneResult.error) {
61	        emit({ type: "auto_done_failed", task_id: taskId, feature_id: featureId, details: doneResult.error });
62	        return;
63	      }
64	
65	      emit({ type: "task_auto_done", task_id: taskId, feature_id: featureId });
66	
67	      if (doneResult.readiedTaskIds.length > 0) {
68	        emit({ type: "auto_ready_cascade", task_id: taskId, feature_id: featureId,
69	               readied_task_ids: doneResult.readiedTaskIds });
70	      }
71	
72	      if (doneResult.allTasksDone) {
73	        emit({ type: "all_tasks_done", feature_id: featureId });
74	      }
75	
76	      break;
77	    }
78	
79	    case "change_requested": {
80	      const mutateErr = mutateTaskYamlDirect({
81	        workspaceRoot, featureId, taskId, taskBranch,
82	        status: "change_requested",
83	        logEntry: { action: "reviewer_complete", by: gitAuthorEmail, note: result.notes ?? "Reviewer requested changes." },
84	        gitAuthorEmail, gitAuthorName,
85	        commitMessage: `chore(${taskId}): reviewer → change_requested`,
86	      });
87	      if (mutateErr) {
88	        emit({ type: "review_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
89	        return;
90	      }
91	      emit({ type: "review_change_requested", task_id: taskId, feature_id: featureId,
