/**
 * Dispatch handler for reviewer-executor completions (handle.kind = "review").
 *
 * Routes by ReviewerResult.terminal_status:
 *   passed           → Auto-Done Writer: mark task done + auto-ready cascade
 *   change_requested → mutate task YAML to change_requested
 *   escalate         → post Slack, mutate task YAML to blocked, emit task_escalated
 *   unknown          → emit review_result_unknown_status
 */

import type { ReviewerResult } from "@workflow/runtime-abi";
import { taskBranchName } from "../paths.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
import { writeDoneAndCascade } from "./write-done-and-cascade.js";
import { readTask } from "../utils/task-yaml-io.js";
import { handleEscalation } from "./escalation-handler.js";

export type ReviewResult = ReviewerResult;

export interface DispatchReviewResultOpts {
  result: ReviewResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  /** Task title from the task YAML — used in Slack escalation message. */
  taskTitle?: string;
  /** Implementation PR URL — used in Slack escalation message. */
  prUrl?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
  const {
    result, workspaceRoot, featureId, taskId,
    taskTitle, prUrl,
    gitAuthorEmail, gitAuthorName, sshKeyPath, emit,
  } = opts;
  const taskBranch = taskBranchName(featureId, taskId);

  switch (result.terminal_status) {
    case "passed": {
      emit({ type: "review_passed", task_id: taskId, feature_id: featureId,
             verdict: result.verdict, confidence: result.confidence, notes: result.notes, review_url: result.review_url });

      let taskPrUrl: string | undefined;
      try {
        const existingTask = readTask(workspaceRoot, featureId, taskId);
        taskPrUrl = existingTask.pr?.url || undefined;
      } catch { /* non-fatal — fall back to no URL */ }

      const doneResult = writeDoneAndCascade({
        workspaceRoot, featureId, taskId, taskBranch,
        prUrl: taskPrUrl,
        gitAuthorEmail, gitAuthorName, sshKeyPath,
      });

      if (doneResult.error) {
        emit({ type: "auto_done_failed", task_id: taskId, feature_id: featureId, details: doneResult.error });
        return;
      }

      emit({ type: "task_auto_done", task_id: taskId, feature_id: featureId });

      if (doneResult.readiedTaskIds.length > 0) {
        emit({ type: "auto_ready_cascade", task_id: taskId, feature_id: featureId,
               readied_task_ids: doneResult.readiedTaskIds });
      }

      if (doneResult.allTasksDone) {
        emit({ type: "all_tasks_done", feature_id: featureId });
      }

      break;
    }

    case "change_requested": {
      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot, featureId, taskId, taskBranch,
        status: "change_requested",
        logEntry: { action: "reviewer_complete", by: gitAuthorEmail, note: result.notes ?? "Reviewer requested changes." },
        gitAuthorEmail, gitAuthorName,
        commitMessage: `chore(${taskId}): reviewer → change_requested`,
      });
      if (mutateErr) {
        emit({ type: "review_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
        return;
      }
      emit({ type: "review_change_requested", task_id: taskId, feature_id: featureId,
             notes: result.notes, review_url: result.review_url });
      break;
    }

    case "escalate":
      await handleEscalation({
        workspaceRoot, featureId, taskId,
        taskTitle, prUrl,
        notes: result.notes,
        reviewUrl: result.review_url,
        gitAuthorEmail, gitAuthorName, sshKeyPath,
        emit,
      });
      break;

    default:
      emit({ type: "review_result_unknown_status", task_id: taskId, feature_id: featureId,
             status: (result as { terminal_status: string }).terminal_status });
  }
}

