1	/**
2	 * Feature Branch Lifecycle Manager (T8).
3	 *
4	 * Runs at orchestrator start, before the main dispatch loop.
5	 * Creates or syncs `feature/{featureId}` on the management (workspace) repo,
6	 * then records `feature_branch` and `feature_branch_base_sha` in status.yaml.
7	 *
8	 * Idempotent: safe to call on every restart. Never overwrites
9	 * `feature_branch_base_sha` once it is set — the drift daemon uses it
10	 * as its comparison baseline.
11	 *
12	 * Git operations are performed in the management repo (workspaceRoot).
13	 */
14	
15	import { execSync } from "node:child_process";
16	import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
17	import { join } from "node:path";
18	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
19	import { buildGitEnv } from "../git-env.js";
20	import {
21	  featureBranchName,
22	  statusYamlAbsPath,
23	  statusYamlRelPath,
24	} from "../paths.js";
25	
26	// ── Types ─────────────────────────────────────────────────────────────────────
27	
28	export interface EnsureFeatureBranchOpts {
29	  /** Absolute path to the management (workspace) repo. */
30	  workspaceRoot: string;
31	  /** Feature directory ID, e.g. "autonomous-task-orchestrator". */
32	  featureId: string;
33	  /** Base branch declared for the management repo in workspace.yaml. */
34	  baseBranch: string;
35	  gitAuthorEmail: string;
36	  gitAuthorName: string;
37	  sshKeyPath?: string;
38	  emit: (event: Record<string, unknown>) => void;
39	}
40	
41	export interface EnsureFeatureBranchResult {
42	  /** The feature branch name, e.g. "feature/autonomous-task-orchestrator". */
43	  featureBranch: string;
44	  /** Whether the branch was created fresh (true) or already existed (false). */
45	  created: boolean;
46	}
47	
48	// ── Helpers ───────────────────────────────────────────────────────────────────
49	
50	interface StatusYaml {
51	  feature_branch?: string | null;
52	  feature_branch_base_sha?: string | null;
53	  [key: string]: unknown;
54	}
55	
56	function execGit(cmd: string, env: NodeJS.ProcessEnv, cwd: string): string {
57	  return execSync(cmd, {
58	    cwd,
59	    env,
60	    encoding: "utf-8",
61	    stdio: "pipe",
62	    timeout: 60_000,
63	  }).trim();
64	}
65	
66	/**
67	 * Returns true if `refs/heads/<branch>` exists on the remote.
68	 * Uses `git ls-remote --exit-code` — exit code 2 means not found.
69	 */
70	function remoteHasBranch(branch: string, env: NodeJS.ProcessEnv, cwd: string): boolean {
71	  try {
72	    execSync(`git ls-remote --exit-code origin "refs/heads/${branch}"`, {
73	      cwd,
74	      env,
75	      encoding: "utf-8",
76	      stdio: "pipe",
77	      timeout: 30_000,
78	    });
79	    return true;
80	  } catch {
81	    return false;
82	  }
83	}
84	
85	// ── Public API ────────────────────────────────────────────────────────────────
86	
87	/**
88	 * Ensure the feature branch exists and is synced with origin.
89	 * Updates status.yaml with `feature_branch` and `feature_branch_base_sha`
90	 * (writes only if unset; never overwrites `feature_branch_base_sha`).
91	 */
92	export function ensureFeatureBranch(
93	  opts: EnsureFeatureBranchOpts,
94	): EnsureFeatureBranchResult {
95	  const {
96	    workspaceRoot,
97	    featureId,
98	    baseBranch,
99	    gitAuthorEmail,
100	    gitAuthorName,
101	    sshKeyPath,
102	    emit,
103	  } = opts;
104	
105	  const featureBranch = featureBranchName(featureId);
106	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
107	
108	  // ── Step 1: Fetch origin ──────────────────────────────────────────────────
109	  execGit("git fetch origin", env, workspaceRoot);
110	
111	  // ── Step 2: Check if feature branch exists on remote ──────────────────────
112	  const existsOnRemote = remoteHasBranch(featureBranch, env, workspaceRoot);
113	
114	  let baseSha: string;
115	  let created: boolean;
116	
117	  if (existsOnRemote) {
118	    // ── Branch already exists — checkout and sync ─────────────────────────
119	    try {
120	      // -B resets the local branch to origin's tip if it already exists locally,
121	      // or creates it fresh. This handles both clean and diverged local states.
122	      execGit(
123	        `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
124	        env,
125	        workspaceRoot,
126	      );
127	    } catch (checkoutErr) {
128	      // Checkout failed (e.g. working tree dirty — should not happen in orchestrator
129	      // context, but handle defensively by re-checkout from a clean base).
130	      emit({
131	        type: "feature_branch_checkout_error",
132	        feature_id: featureId,
133	        details: String(checkoutErr),
134	        action: "recovering_from_base",
135	      });
136	      execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
137	      try {
138	        execGit(`git branch -D "${featureBranch}"`, env, workspaceRoot);
139	      } catch {
140	        // Branch may not exist locally yet — ignore.
141	      }
142	      execGit(
143	        `git checkout -b "${featureBranch}" "origin/${featureBranch}"`,
144	        env,
145	        workspaceRoot,
146	      );
147	    }
148	
149	    // Compute merge-base — used when status.yaml has no feature_branch_base_sha.
150	    // git merge-base returns the common ancestor of the feature branch and origin base.
151	    try {
152	      baseSha = execGit(
153	        `git merge-base "${featureBranch}" "origin/${baseBranch}"`,
154	        env,
155	        workspaceRoot,
156	      );
157	    } catch {
158	      // Fallback: use the first commit on the feature branch relative to base.
159	      baseSha = execGit(
160	        `git rev-parse "origin/${baseBranch}"`,
161	        env,
162	        workspaceRoot,
163	      );
164	    }
165	
166	    created = false;
167	    emit({
168	      type: "feature_branch_synced",
169	      feature_id: featureId,
170	      branch: featureBranch,
171	    });
172	  } else {
173	    // ── Branch does not exist — create from base branch tip ───────────────
174	    execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
175	    execGit(`git pull origin "${baseBranch}"`, env, workspaceRoot);
176	    baseSha = execGit("git rev-parse HEAD", env, workspaceRoot);
177	
178	    execGit(`git checkout -b "${featureBranch}"`, env, workspaceRoot);
179	    execGit(`git push -u origin "${featureBranch}"`, env, workspaceRoot);
180	
181	    created = true;
182	    emit({
183	      type: "feature_branch_created",
184	      feature_id: featureId,
185	      branch: featureBranch,
186	      base_sha: baseSha,
187	    });
188	  }
189	
190	  // ── Step 3: Update status.yaml (only when fields are unset) ──────────────
191	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
192	  if (!existsSync(statusPath)) {
193	    emit({
194	      type: "feature_status_yaml_not_found",
195	      feature_id: featureId,
196	      path: statusPath,
197	    });
198	    return { featureBranch, created };
199	  }
200	
201	  const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
202	
203	  let changed = false;
204	  if (!statusYaml.feature_branch) {
205	    statusYaml.feature_branch = featureBranch;
206	    changed = true;
207	  }
208	  // Never overwrite feature_branch_base_sha — it is the drift baseline.
209	  if (!statusYaml.feature_branch_base_sha) {
210	    statusYaml.feature_branch_base_sha = baseSha;
211	    changed = true;
212	  }
213	
214	  if (changed) {
215	    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");
216	
217	    const relPath = statusYamlRelPath(featureId);
218	    execGit(`git add "${relPath}"`, env, workspaceRoot);
219	    try {
220	      execGit(
221	        `git commit -m "chore(${featureId}): record feature branch metadata in status.yaml"`,
222	        env,
223	        workspaceRoot,
224	      );
225	      execGit(`git push origin "${featureBranch}"`, env, workspaceRoot);
226	    } catch (commitErr) {
227	      const stderr = (commitErr as { stderr?: string }).stderr ?? "";
228	      if (!stderr.includes("nothing to commit")) {
229	        throw commitErr;
230	      }
231	      // Nothing to commit — status.yaml already had correct values. Continue.
232	    }
233	
234	    emit({
235	      type: "feature_branch_status_updated",
236	      feature_id: featureId,
237	      branch: featureBranch,
238	      fields_written: Object.keys(statusYaml).filter(
239	        (k) => k === "feature_branch" || k === "feature_branch_base_sha",
240	      ),
241	    });
242	  }
243	
244	  return { featureBranch, created };
245	}
246	
247	// ── Multi-feature scan ────────────────────────────────────────────────────────
248	
249	export interface RunFeatureBranchLifecycleOpts {
250	  workspaceRoot: string;
251	  /** Base branch for the management repo. */
252	  baseBranch: string;
253	  gitAuthorEmail: string;
254	  gitAuthorName: string;
255	  sshKeyPath?: string;
256	  emit: (event: Record<string, unknown>) => void;
257	}
258	
259	/**
260	 * Scan all feature directories in the workspace and call `ensureFeatureBranch`
261	 * for each one that has a status.yaml. Non-throwing: errors per-feature are
262	 * emitted and the scan continues.
263	 *
264	 * Called at orchestrator start (once) before `runOneCycle` begins.
265	 */
266	export function runFeatureBranchLifecycle(
267	  opts: RunFeatureBranchLifecycleOpts,
268	): void {
269	  const { workspaceRoot, baseBranch, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;
270	
271	  const featuresDir = join(workspaceRoot, "docs", "features");
272	  if (!existsSync(featuresDir)) {
273	    emit({ type: "feature_branch_lifecycle_no_features_dir", workspace: workspaceRoot });
274	    return;
275	  }
276	
277	  let featureDirs: string[];
278	  try {
279	    featureDirs = readdirSync(featuresDir, { withFileTypes: true })
280	      .filter((e) => e.isDirectory())
281	      .map((e) => e.name);
282	  } catch (e) {
283	    emit({ type: "feature_branch_lifecycle_scan_error", workspace: workspaceRoot, details: String(e) });
284	    return;
285	  }
286	
287	  for (const featureId of featureDirs) {
288	    const statusPath = join(featuresDir, featureId, "status.yaml");
289	    if (!existsSync(statusPath)) continue;
290	
