/**
 * Handoff Trigger (T9) — fires after the Auto-Done Writer marks the last task done.
 *
 * Steps:
 *   1. Read all task YAMLs for the feature and collect completed task metadata.
 *   2. Generate docs/features/{featureId}/handoffs/handoff.md.
 *   3. Commit handoff.md to the feature branch and push.
 *   4. Open a PR: feature/{featureId} → baseBranch via GitHub API.
 *   5. Write handoff_pr_url, transition feature_status/current_stage in status.yaml.
 *   6. Commit and push status.yaml changes.
 *   7. Notify operator via SLACK_WEBHOOK_URL (if set).
 *   8. Emit feature_handoff_triggered and handoff_pr_opened events.
 */

import { execSync, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import {
  featureBranchName,
  featuresRoot,
  statusYamlAbsPath,
  statusYamlRelPath,
  TASKS_DIR,
} from "../paths.js";
import { curlJson } from "../utils/curl-json.js";
import type { Task } from "../types/task.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface HandoffTriggerOpts {
  workspaceRoot: string;
  featureId: string;
  /** Feature branch base branch (e.g. "main"). */
  baseBranch: string;
  /** GitHub personal access token for PR creation. */
  githubToken: string;
  /** GitHub owner extracted from management repo SSH URL. */
  repoOwner: string;
  /** GitHub repo name extracted from management repo SSH URL. */
  repoName: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface HandoffTriggerResult {
  /** Error string if the operation failed; undefined on success. */
  error?: string;
  /** URL of the opened feature branch PR. */
  prUrl?: string;
}

interface StatusYaml {
  feature_status?: string;
  current_stage?: string;
  handoff_pr_url?: string | null;
  stages?: {
    handoff?: {
      review_status?: string;
      pr_url?: string | null;
      [key: string]: unknown;
    };
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function execGit(
  cmd: string,
  env: NodeJS.ProcessEnv,
  cwd: string,
): string {
  return execSync(cmd, {
    cwd,
    env,
    encoding: "utf-8",
    stdio: "pipe",
    timeout: 60_000,
  }).trim();
}

/**
 * Read all task YAMLs for a feature directory.
 * Returns an empty array if the tasks directory does not exist.
 */
function readAllTasks(workspaceRoot: string, featureId: string): Task[] {
  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  let files: string[] = [];
  try {
    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
  } catch {
    return [];
  }
  const tasks: Task[] = [];
  for (const file of files) {
    try {
      tasks.push(parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task);
    } catch {
      /* skip unreadable files */
    }
  }
  return tasks;
}

/**
 * Read product-spec.md for the feature and extract a brief summary.
 * Returns a placeholder if the file is missing or unreadable.
 */
function readProductSpecSummary(workspaceRoot: string, featureId: string): string {
  const specPath = join(featuresRoot(workspaceRoot), featureId, "product-spec.md");
  if (!existsSync(specPath)) return "_No product spec found._";
  try {
    const content = readFileSync(specPath, "utf-8");
    // Extract first non-empty paragraph after the first heading.
    const lines = content.split("\n");
    let inContent = false;
    const summaryLines: string[] = [];
    for (const line of lines) {
      if (!inContent && line.startsWith("#")) { inContent = true; continue; }
      if (!inContent) continue;
      if (line.trim() === "" && summaryLines.length > 0) break;
      if (line.trim() !== "") summaryLines.push(line.trim());
    }
    return summaryLines.length > 0 ? summaryLines.join(" ") : "_See product spec for details._";
  } catch {
    return "_Error reading product spec._";
  }
}

/**
 * Aggregate files changed across all task PRs using the GitHub Compare API.
 * Returns a markdown list; falls back to a placeholder when no PRs are available.
 */
async function fetchFilesChanged(
  tasks: Task[],
  githubToken: string,
  repoOwner: string,
  repoName: string,
): Promise<string> {
  const fileSet = new Set<string>();
  for (const task of tasks) {
    const prUrl = task.pr?.url;
    if (!prUrl) continue;
    const prMatch = /\/pull\/(\d+)$/.exec(prUrl);
    if (!prMatch) continue;
    const prNumber = prMatch[1];
    try {
      const files = curlJson([
        "-s",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}/files`,
      ]) as Array<{ filename: string }>;
      if (Array.isArray(files)) {
        for (const f of files) {
          if (f.filename) fileSet.add(f.filename);
        }
      }
    } catch {
      /* non-fatal — skip this PR's files */
    }
  }
  if (fileSet.size === 0) return "_No PR file data available._";
  return [...fileSet].sort().map((f) => `- \`${f}\``).join("\n");
}

/**
 * Extract reviewer notes from the last reviewer_complete log entry (if any).
 */
function extractReviewerNotes(task: Task): string {
  const entry = [...task.log].reverse().find((e) => e.action === "reviewer_complete");
  return entry?.note ? String(entry.note) : "—";
}

/**
 * Generate the handoff document markdown from task data.
 */
async function generateHandoffDoc(
  opts: HandoffTriggerOpts,
  tasks: Task[],
  featureTitle: string,
): Promise<string> {
  const { workspaceRoot, featureId, githubToken, repoOwner, repoName } = opts;

  const summary = readProductSpecSummary(workspaceRoot, featureId);

  // Tasks Completed table
  const taskRows = tasks
    .filter((t) => t.status === "done")
    .map((t) => {
      const prUrl = t.pr?.url ? `[PR](${t.pr.url})` : "—";
      const notes = extractReviewerNotes(t);
      return `| ${t.id} — ${t.title} | ${prUrl} | ${notes} |`;
    })
    .join("\n");

  // Files changed
  const filesChanged = await fetchFilesChanged(tasks, githubToken, repoOwner, repoName);

  // Audit trail
  const auditRows = tasks
    .flatMap((t) =>
      t.log.map((entry) => ({
        action: `${t.id}: ${entry.action}`,
        actor: entry.by,
        at: entry.at,
      })),
    )
    .sort((a, b) => a.at.localeCompare(b.at))
    .map((e) => `| ${e.action} | ${e.actor} | ${e.at} |`)
    .join("\n");

  // Cancelled tasks (follow-up items)
  const cancelledTasks = tasks.filter((t) => t.status === "cancelled");
  const followUp = cancelledTasks.length > 0
    ? cancelledTasks.map((t) => `- ${t.id} — ${t.title} (cancelled)`).join("\n")
    : "_None identified._";

  return [
    `# Handoff — ${featureTitle}`,
    "",
    "## Summary",
    summary,
    "",
    "## Tasks Completed",
    "| Task | PR | Reviewer Notes |",
    "|---|---|---|",
    taskRows || "| — | — | — |",
    "",
    "## Deviations from Technical Design",
    "_See reviewer notes in Tasks Completed table above._",
    "",
    "## Files Changed",
    filesChanged,
    "",
    "## Follow-up Items",
    followUp,
    "",
    "## Audit Trail",
    "| Action | Actor | Timestamp |",
    "|---|---|---|",
    auditRows || "| — | — | — |",
  ].join("\n");
}

/**
 * Open a PR from featureBranch → baseBranch on the management repo.
 * Returns the PR URL on success; throws on failure.
 */
function openFeaturePr(opts: {
  featureId: string;
  featureBranch: string;
  baseBranch: string;
  githubToken: string;
  repoOwner: string;
  repoName: string;
  title: string;
  body: string;
}): { prUrl: string; alreadyExisted: boolean } {
  const { featureBranch, baseBranch, githubToken, repoOwner, repoName, title, body } = opts;

  // Check for existing open PR
  const encodedHead = encodeURIComponent(`${repoOwner}:${featureBranch}`);
  const listUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls?head=${encodedHead}&state=open`;
  const existing = curlJson([
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    listUrl,
  ]) as Array<{ html_url: string }>;

  if (Array.isArray(existing) && existing.length > 0) {
    return { prUrl: existing[0].html_url, alreadyExisted: true };
  }

  const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
  const created = curlJson([
    "-s", "-X", "POST",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    "-H", "Content-Type: application/json",
    "-d", JSON.stringify({ title, body, head: featureBranch, base: baseBranch }),
    createUrl,
  ]) as { html_url?: string };

  if (!created.html_url) {
    throw new Error(`GitHub API PR creation failed: ${JSON.stringify(created)}`);
  }

  return { prUrl: created.html_url, alreadyExisted: false };
}

/**
 * Post a Slack notification for the handoff.
 */
async function postHandoffSlack(
  opts: HandoffTriggerOpts,
  featureTitle: string,
  prUrl: string,
  webhookUrl: string,
): Promise<void> {
  const payload = {
    text: `[Handoff] Feature ${opts.featureId} is ready for review`,
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: `✅ Feature handoff: ${featureTitle}` },
      },
      {
        type: "section",
        fields: [
          { type: "mrkdwn", text: `*Feature:*\n${opts.featureId}` },
          { type: "mrkdwn", text: `*Handoff PR:*\n<${prUrl}|View PR>` },
        ],
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "_All tasks are complete. The handoff document has been generated and a PR is open for review._",
        },
      },
    ],
  };
  const resp = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!resp.ok) {
    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Fire the Handoff Trigger for a feature whose last task was just marked done.
 *
 * Non-throwing: returns an error string on failure so the caller can decide
 * how to surface the error.
 */
export async function fireHandoffTrigger(
  opts: HandoffTriggerOpts,
): Promise<HandoffTriggerResult> {
  const {
    workspaceRoot,
    featureId,
    baseBranch,
    githubToken,
    repoOwner,
    repoName,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  const featureBranch = featureBranchName(featureId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  emit({ type: "feature_handoff_triggered", feature_id: featureId });

  // ── Step 1: Checkout feature branch ──────────────────────────────────────
  try {
    execGit("git fetch origin", env, workspaceRoot);
    execGit(
      `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    return { error: `Failed to checkout feature branch: ${String(e)}` };
  }

  // ── Step 2: Read all task YAMLs ───────────────────────────────────────────
  const tasks = readAllTasks(workspaceRoot, featureId);
  if (tasks.length === 0) {
    return { error: `No task YAMLs found for feature "${featureId}"` };
  }

  // Read feature title from status.yaml (or fall back to featureId)
  let featureTitle = featureId;
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  let statusYaml: StatusYaml = {};
  if (existsSync(statusPath)) {
    try {
      statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
      if (typeof statusYaml.title === "string") featureTitle = statusYaml.title;
    } catch {
      /* use featureId as fallback */
    }
  }

  // ── Step 3: Generate handoff.md ───────────────────────────────────────────
  let handoffContent: string;
  try {
    handoffContent = await generateHandoffDoc(opts, tasks, featureTitle);
  } catch (e) {
    return { error: `Failed to generate handoff document: ${String(e)}` };
  }

  const handoffsDir = join(featuresRoot(workspaceRoot), featureId, "handoffs");
  const handoffPath = join(handoffsDir, "handoff.md");
  const handoffRelPath = join("docs", "features", featureId, "handoffs", "handoff.md");

  try {
    mkdirSync(handoffsDir, { recursive: true });
    writeFileSync(handoffPath, handoffContent, "utf-8");
  } catch (e) {
    return { error: `Failed to write handoff.md: ${String(e)}` };
  }

  // ── Step 4: Commit handoff.md ─────────────────────────────────────────────
  try {
    execGit(`git add "${handoffRelPath}"`, env, workspaceRoot);
    execGit(
      `git commit -m "chore(${featureId}): generate handoff document"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    const stderr = (e as { stderr?: string }).stderr ?? String(e);
    if (!stderr.includes("nothing to commit")) {
      return { error: `Failed to commit handoff.md: ${String(e)}` };
    }
  }

  // ── Step 5: Open feature PR ───────────────────────────────────────────────
  let prUrl: string;
  let alreadyExisted: boolean;
  try {
    const prResult = openFeaturePr({
      featureId,
      featureBranch,
      baseBranch,
      githubToken,
      repoOwner,
      repoName,
      title: `feat(${featureId}): handoff — ${featureTitle}`,
      body: `## Feature Handoff\n\nFeature: \`${featureId}\`\nBranch: \`${featureBranch}\`\n\nAll tasks are complete. This PR merges the feature branch into \`${baseBranch}\`.`,
    });
    prUrl = prResult.prUrl;
    alreadyExisted = prResult.alreadyExisted;
  } catch (e) {
    return { error: `Failed to open feature PR: ${String(e)}` };
  }

  emit({
    type: "handoff_pr_opened",
    feature_id: featureId,
    pr_url: prUrl,
    already_existed: alreadyExisted,
  });

  // ── Step 6: Update status.yaml ────────────────────────────────────────────
  try {
    statusYaml.handoff_pr_url = prUrl;
    statusYaml.feature_status = "in_handoff";
    statusYaml.current_stage = "handoff";
    if (statusYaml.stages?.handoff) {
      statusYaml.stages.handoff.pr_url = prUrl;
    }
    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

    const statusRelPath = statusYamlRelPath(featureId);
    execGit(`git add "${statusRelPath}"`, env, workspaceRoot);
    try {
      execGit(
        `git commit -m "chore(${featureId}): transition to in_handoff; record handoff PR"`,
        env,
        workspaceRoot,
      );
    } catch (e) {
      const stderr = (e as { stderr?: string }).stderr ?? String(e);
      if (!stderr.includes("nothing to commit")) throw e;
    }
  } catch (e) {
    // Non-fatal — PR is already open; log but don't fail.
    emit({
      type: "handoff_status_yaml_update_failed",
      feature_id: featureId,
      details: String(e),
    });
  }

  // ── Step 7: Push feature branch ───────────────────────────────────────────
  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    emit({
      type: "handoff_push_failed",
      feature_id: featureId,
      details: push.stderr,
    });
    // Non-fatal — the handoff doc and PR are still created.
  }

  // ── Step 8: Slack notification ────────────────────────────────────────────
  const webhookUrl = process.env["SLACK_WEBHOOK_URL"];
  if (webhookUrl) {
    try {
      await postHandoffSlack(opts, featureTitle, prUrl, webhookUrl);
    } catch (e) {
      emit({
        type: "handoff_slack_failed",
        feature_id: featureId,
        error: String(e),
      });
    }
  } else {
    emit({ type: "handoff_slack_skipped", feature_id: featureId });
  }

  return { prUrl };
}

