/**
 * Tests for T9 — handoff-trigger.ts
 *
 * 1. All tasks done → fireHandoffTrigger generates handoff.md, opens PR, updates status.yaml,
 *    emits feature_handoff_triggered and handoff_pr_opened.
 * 2. Some tasks cancelled + rest done → trigger still fires.
 * 3. One task still in_progress → trigger must NOT fire (tested via checkAllTasksDone logic
 *    at the dispatch-review-result integration boundary).
 * 4. Slack webhook absent → emits handoff_slack_skipped.
 * 5. Slack webhook present → posts to webhook.
 * 6. Slack POST failure → emits handoff_slack_failed but does not fail the trigger.
 * 7. feature PR already exists → reuses existing PR (idempotent).
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
  existsSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

// ── Mock child_process ────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-handoff-feature";
const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
const BASE_BRANCH = "main";
const GITHUB_TOKEN = "ghp_test_token";
const REPO_OWNER = "test-owner";
const REPO_NAME = "test-repo";
const HANDOFF_PR_URL = "https://github.com/test-owner/test-repo/pull/99";
const ORIGINAL_SLACK_URL = process.env["SLACK_WEBHOOK_URL"];

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "workflow",
    status: "done",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: { actor_type: "agent", last_updated_by: "bot@test.com", last_updated_at: "2026-05-08T00:00:00Z" },
    pr: { url: `https://github.com/${REPO_OWNER}/${REPO_NAME}/pull/${parseInt(id.slice(1))}`, status: "merged" },
    workspace_pr: null,
    log: [
      { action: "done", by: "bot@test.com", at: "2026-05-08T10:00:00Z", note: "Done." },
    ],
    ...overrides,
  };
}

function makeStatusYaml(): Record<string, unknown> {
  return {
    feature_id: FEATURE_ID,
    title: "Test Handoff Feature",
    feature_status: "ready_for_implementation",
    current_stage: "tasks",
    feature_branch: FEATURE_BRANCH,
    feature_branch_base_sha: "abc123",
    handoff_pr_url: null,
    drift_detected: false,
    drift_reason: null,
    stages: {
      handoff: {
        review_status: "draft",
        reviewed_by: null,
        reviewed_at: null,
        pr_url: null,
      },
    },
  };
}

// ── Temp workspace helpers ─────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(tasks: Task[], withStatusYaml = true): string {
  const wsDir = mkdtempSync(join(tmpdir(), "handoff-trigger-"));
  tmpDirs.push(wsDir);

  const tasksDir = join(wsDir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });

  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }

  if (withStatusYaml) {
    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
    writeFileSync(statusPath, yamlStringify(makeStatusYaml()), "utf-8");
  }

  // Write a minimal product spec
  const specPath = join(wsDir, "docs", "features", FEATURE_ID, "product-spec.md");
  writeFileSync(specPath, "# Test Feature\n\nThis feature implements autonomous task orchestration.\n", "utf-8");

  return wsDir;
}

function makePushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function makeCurlNoExistingPr(): string {
  return JSON.stringify([]); // no existing open PR
}

function makeCurlCreatedPr(): string {
  return JSON.stringify({ html_url: HANDOFF_PR_URL, number: 99 });
}

function makeCurlFilesResponse(): string {
  return JSON.stringify([
    { filename: "runtime/orchestrator/src/handoff/handoff-trigger.ts" },
    { filename: "runtime/orchestrator/tests/handoff-trigger.test.ts" },
  ]);
}

// ── Setup / teardown ──────────────────────────────────────────────────────────

beforeEach(() => {
  delete process.env["SLACK_WEBHOOK_URL"];
});

afterEach(() => {
  if (ORIGINAL_SLACK_URL !== undefined) {
    process.env["SLACK_WEBHOOK_URL"] = ORIGINAL_SLACK_URL;
  } else {
    delete process.env["SLACK_WEBHOOK_URL"];
  }
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
  vi.unstubAllGlobals();
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("fireHandoffTrigger — all tasks done", () => {
  it("generates handoff.md, opens PR, updates status.yaml, emits correct events", async () => {
    const tasks = [makeTask("T1"), makeTask("T2"), makeTask("T3")];
