    expect(events.some((e) => e.type === "handoff_slack_skipped")).toBe(true);

    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.pr_url).toBe(HANDOFF_PR_URL);
    expect(prEvent?.already_existed).toBe(false);
