/** Set up curlJson mock: no existing PR → create new PR; file listing returns files. */
function setupCurlMock(curlJson: ReturnType<typeof vi.fn>, existingPrUrl?: string) {
  curlJson.mockImplementation((args: string[]) => {
    const lastArg = args[args.length - 1] ?? "";
    if (lastArg.includes("/files")) {
      return [
        { filename: "runtime/orchestrator/src/handoff/handoff-trigger.ts" },
        { filename: "runtime/orchestrator/tests/handoff-trigger.test.ts" },
      ];
    }
    if (lastArg.includes("state=open")) {
      return existingPrUrl ? [{ html_url: existingPrUrl, number: 99 }] : [];
    }
    // PR creation response
    return { html_url: HANDOFF_PR_URL, number: 99 };
  });
}

// ── Setup / teardown ──────────────────────────────────────────────────────────

beforeEach(() => {
  delete process.env["SLACK_WEBHOOK_URL"];
});

afterEach(() => {
  if (ORIGINAL_SLACK_URL !== undefined) {
    process.env["SLACK_WEBHOOK_URL"] = ORIGINAL_SLACK_URL;
  } else {
    delete process.env["SLACK_WEBHOOK_URL"];
  }
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
  vi.unstubAllGlobals();
});

