    expect(existsSync(handoffPath)).toBe(true);
    const handoffContent = readFileSync(handoffPath, "utf-8");
    expect(handoffContent).toContain("# Handoff");
    expect(handoffContent).toContain("## Tasks Completed");
    expect(handoffContent).toContain("## Audit Trail");

    // status.yaml updated
    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
