    expect(events.some((e) => e.type === "handoff_slack_skipped")).toBe(true);

    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.pr_url).toBe(HANDOFF_PR_URL);
    expect(prEvent?.already_existed).toBe(false);
  });
});

describe("fireHandoffTrigger — some tasks cancelled + rest done", () => {
  it("still fires the trigger when cancelled tasks are present", async () => {
    const tasks = [
      makeTask("T1"),
      makeTask("T2", { status: "cancelled", pr: { url: "", status: "not_created" } }),
      makeTask("T3"),
    ];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockReturnValue(Buffer.from("") as unknown as string);
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.error).toBeUndefined();
    expect(result.prUrl).toBe(HANDOFF_PR_URL);
    expect(events.some((e) => e.type === "feature_handoff_triggered")).toBe(true);
    expect(events.some((e) => e.type === "handoff_pr_opened")).toBe(true);
  });
});

describe("fireHandoffTrigger — existing open PR (idempotent)", () => {
  it("reuses existing feature PR without creating a duplicate", async () => {
    const tasks = [makeTask("T1"), makeTask("T2")];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockReturnValue(Buffer.from("") as unknown as string);
