      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.prUrl).toBe(HANDOFF_PR_URL);
    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.already_existed).toBe(true);
  });
});

describe("fireHandoffTrigger — Slack notification", () => {
  it("posts to Slack webhook when SLACK_WEBHOOK_URL is set", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/TEST";
    const tasks = [makeTask("T1")];
    const wsDir = makeWorkspace(tasks);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockImplementation((cmd, args) => {
      if (cmd === "curl") {
        const argsArr = args as string[];
        const lastArg = argsArr[argsArr.length - 1] ?? "";
        if (lastArg.includes("/files")) return { ...makePushSuccess(), stdout: makeCurlFilesResponse() };
        if (lastArg.includes("state=open")) return { ...makePushSuccess(), stdout: makeCurlNoExistingPr() };
        return { ...makePushSuccess(), stdout: makeCurlCreatedPr() };
      }
      return makePushSuccess();
    });

    const mockFetch = vi.fn().mockResolvedValue({ ok: true, text: async () => "ok" });
    vi.stubGlobal("fetch", mockFetch);

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    expect(url).toBe("https://hooks.slack.com/services/TEST");
    expect(init.method).toBe("POST");
    const body = JSON.parse(init.body as string) as { text: string };
    expect(body.text).toContain(FEATURE_ID);
    expect(events.some((e) => e.type === "handoff_slack_skipped")).toBe(false);
  });

  it("emits handoff_slack_failed when Slack POST fails but does not fail the trigger", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/BAD";
    const tasks = [makeTask("T1")];
    const wsDir = makeWorkspace(tasks);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockImplementation((cmd, args) => {
      if (cmd === "curl") {
        const argsArr = args as string[];
        const lastArg = argsArr[argsArr.length - 1] ?? "";
        if (lastArg.includes("/files")) return { ...makePushSuccess(), stdout: makeCurlFilesResponse() };
        if (lastArg.includes("state=open")) return { ...makePushSuccess(), stdout: makeCurlNoExistingPr() };
        return { ...makePushSuccess(), stdout: makeCurlCreatedPr() };
      }
      return makePushSuccess();
    });

    const mockFetch = vi.fn().mockResolvedValue({
      ok: false, status: 500,
      text: async () => "Internal Server Error",
    });
    vi.stubGlobal("fetch", mockFetch);

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    // PR was still created
    expect(result.prUrl).toBe(HANDOFF_PR_URL);
    expect(result.error).toBeUndefined();
