    expect(events.some((e) => e.type === "handoff_slack_failed")).toBe(true);
  });
});

describe("dispatchReviewResult integration — handoff trigger invoked when all tasks done", () => {
  it("does not invoke handoff trigger when one task is still in_progress", async () => {
    // This tests the allTasksDone guard in write-done-and-cascade.ts via a mock.
    // We verify that when allTasksDone is false, no feature_handoff_triggered event is emitted.

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockImplementation(() => makePushSuccess());

    // Provide a workspace with one task still in_progress
    const wsDir = mkdtempSync(join(tmpdir(), "handoff-no-trigger-"));
    tmpDirs.push(wsDir);

    const tasksDir = join(wsDir, "docs", "features", FEATURE_ID, "tasks");
    mkdirSync(tasksDir, { recursive: true });

    const doneTask = makeTask("T1");
    const inProgressTask = makeTask("T2", { status: "in_progress" });
    writeFileSync(join(tasksDir, "T1.yaml"), yamlStringify(doneTask), "utf-8");
    writeFileSync(join(tasksDir, "T2.yaml"), yamlStringify(inProgressTask), "utf-8");

    // Write workspace.yaml so parseManagementRepoCoords can read it
    writeFileSync(
      join(wsDir, "workspace.yaml"),
      yamlStringify({
        management_repo: "management-repo",
        repos: [
          {
            id: "management-repo",
            github: "git@github.com:test-owner/test-repo.git",
            base_branch: "main",
          },
        ],
      }),
      "utf-8",
    );

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "pass", confidence: 0.9, notes: "LGTM" },
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: "T1",
      gitAuthorEmail: "bot@test.com",
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    // task_auto_done should be emitted
    expect(events.some((e) => e.type === "task_auto_done")).toBe(true);
    // feature_handoff_triggered should NOT be emitted since T2 is still in_progress
    expect(events.some((e) => e.type === "feature_handoff_triggered")).toBe(false);
    // all_tasks_done should NOT be emitted
    expect(events.some((e) => e.type === "all_tasks_done")).toBe(false);
  });
});

